using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class LeaveIntegrityTests
{
 class User:ICurrentUser{public string Email=>"leave@example.local";public int? EmployeeId=>6;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>true;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static LeaveService S(AppDbContext d){var u=new User();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a));}
 [Theory][InlineData(false)][InlineData(true)]public void ApprovedCancellationRejectsMissingOrInsufficientBalance(bool missing){var r=new LeaveRequest{StartDate=new(2027,6,1),Days=2,Status=RequestStatus.Approved,LeaveType=new(){DeductsBalance=true}};var b=new LeaveBalance{Used=1};Assert.Throws<DomainException>(()=>r.CancelApproved(missing?null:b,new(2026,11,24),DateTime.UtcNow));Assert.Equal(RequestStatus.Approved,r.Status);Assert.Equal(1,b.Used);}
 [Fact]public void NonDeductingCancellationDoesNotRequireBalance(){var r=new LeaveRequest{StartDate=new(2027,6,1),Days=2,Status=RequestStatus.Approved,LeaveType=new(){DeductsBalance=false}};r.CancelApproved(null,new(2026,11,24),DateTime.UtcNow);Assert.Equal(RequestStatus.Cancelled,r.Status);}
 [Fact]public void SameCalendarDayTimesUseDateSemantics(){var t=new LeaveType{Id=1,IsPaid=true,DeductsBalance=false};var e=new Employee{Id=6,Status=EmployeeStatus.Active};var r=LeaveRequest.Create(e,t,null,new(2026,12,23,17,0,0),new(2026,12,23,9,0,0),"Fictional date test",null,new(2026,11,24));Assert.Equal(1,r.Days);Assert.Equal(r.StartDate,r.EndDate);}
 [Fact]public async Task EntitlementReductionCannotCreateNegativeBalanceOrLedgerEntry(){await using var d=await Db();var s=S(d);var b=(await s.BalancesAsync(6,2027)).First();b.Used=4;b.CarriedOver=0;await d.SaveAsync();var before=await d.Set<LeaveTransaction>().CountAsync();await Assert.ThrowsAsync<DomainException>(()=>s.AdjustBalanceAsync(6,b.LeaveTypeId,2027,0,"Fictional invalid reduction"));var current=await d.Set<LeaveBalance>().SingleAsync(x=>x.Id==b.Id);Assert.True(current.Remaining>=0);Assert.Equal(before,await d.Set<LeaveTransaction>().CountAsync());await s.AdjustBalanceAsync(6,b.LeaveTypeId,2027,4,"Fictional exact floor");Assert.Equal(0,current.Remaining);}
 [Fact]public async Task MissingCancellationBalanceLeavesApprovedRequestAndEvidenceUnchanged(){await using var d=await Db();var r=new LeaveRequest{EmployeeId=6,LeaveTypeId=1,StartDate=new(2027,6,1),EndDate=new(2027,6,1),Days=1,Status=RequestStatus.Approved};d.Add(r);await d.SaveAsync();var actions=await d.Set<ApprovalAction>().CountAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).CancelApprovedAsync(r.Id,"Fictional missing balance"));Assert.Equal(RequestStatus.Approved,(await d.Set<LeaveRequest>().FindAsync(r.Id))!.Status);Assert.Equal(actions,await d.Set<ApprovalAction>().CountAsync());Assert.False(await d.Set<LeaveTransaction>().AnyAsync(x=>x.RequestId==r.Id&&x.Kind=="Cancellation"));}
}
